package com.motionecosystem.participantmeasurements;
import io.swagger.v3.oas.annotations.Operation;
import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/specialist/clients/{participantId}/measurements") class SpecialistParticipantMeasurementController { private final ParticipantMeasurementService service; private final SpecialistParticipantMeasurementApplicationService recording; SpecialistParticipantMeasurementController(ParticipantMeasurementService s,SpecialistParticipantMeasurementApplicationService r){service=s;recording=r;} @GetMapping("/catalog") @Operation(operationId="participantMeasurementCatalog") List<com.motionecosystem.participant.api.ParticipantMetricCatalog.ParticipantMeasurementPresetView> participantMeasurementCatalog(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID participantId){return service.catalog(jwt.getSubject(),participantId);}@GetMapping @Operation(operationId="listParticipantMeasurements") List<ParticipantMeasurementService.ParticipantMeasurementView> listParticipantMeasurements(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID participantId,@RequestParam(required=false) Integer limit){return service.list(jwt.getSubject(),participantId,limit);}@PostMapping @Operation(operationId="recordParticipantMeasurement") ParticipantMeasurementService.ParticipantMeasurementView recordParticipantMeasurement(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID participantId,@RequestHeader("Idempotency-Key") String key,@RequestBody ParticipantMeasurementService.ParticipantMeasurementCommand command){return recording.record(jwt.getSubject(),participantId,key,command);} }
